# KITCHEN DEMO mix: dialogue + the phone buzzing on the table + the pick-up + fridge hum and room tone + a soft piano.
# Everything is generated by kit/engine/audio/sfxlib.py. kit/make.py runs this after the footstep probe.
import os, sys, numpy as np
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.dirname(HERE)
KIT = os.environ.get('SS_KIT') or next((os.path.join(p, 'kit') for p in [os.path.dirname(ROOT), os.path.dirname(os.path.dirname(ROOT)), os.getcwd()]
                                        if os.path.exists(os.path.join(p, 'kit', 'engine', 'audio', 'sfxlib.py'))), None)
if not KIT: raise SystemExit('cannot find kit/: run this through  python kit/make.py <film> sound')
sys.path.insert(0, os.path.join(KIT, 'engine', 'audio'))
from sfxlib import *
TL = init(ROOT); SC = G['SC']
have = lambda s: s in SC
if have('kitchen'): rooms({'kitchen': (0.4, 10, 0.05)})
n = place_dialogue(pan={'ana': -0.2, 'ben': 0.15}); print('voice lines placed', n)

for e in TL['sfx']:
    t, nm = e['t'], e['name']
    if nm == 'buzz': fxat(t, buzz_phone(1.6, 1.0), 0.9, 0.15); fxat(t, thud(0.08, 120, 1.6) * 0.3, 0.5, 0.15)   # the table rattles
    if nm == 'pickup': fxat(t - 0.45, buzz_phone(0.95, 1.0), 0.8, 0.15); fxat(t + 0.55, thud(0.12, 320, 0.06), 0.5, 0.15); fxat(t + 0.6, clink(0.05), 0.2, 0.15)
for e in G['EV'].get('steps', []):
    fxat(e['t'], footstep('stone', 0.8), 0.28, float(np.clip(e['x'] / 4, -0.5, 0.5)))

def g_kitchen(n, s): a, b = roomtone(n); h = hum_bed(n, 50, 0.5); return a * 0.45 + h[0], b * 0.45 + h[1]   # fridge hum
if have('kitchen'): seg(['kitchen'], g_kitchen, 0.8)

if have('kitchen'):
    a, b = cue('kitchen'); chords(a + 0.3, b, ['Fmaj7', 'C', 'Am', 'G'], 2.6, pad, 0.03)
    for i, nt in enumerate([72, 76, 79, 77]): mput(a + 2.0 + i * 2.2, piano(mtof(nt), 2.0, 0.08))
if have('endcard'): a, b = cue('endcard'); mput(a, music_box(mtof(76), 4, 0.3))

mixdown(ROOT + '/audio/final_audio.wav', amb_gains={'endcard': 0.0}, mus_gains={'endcard': 1.0}, mus_default=0.6)
